// generated by beeline from 3 recorded runs.
// GET https://zed.dev/extensions
// 2026-09-20T03:03:04.474Z
//
// this site has no api — the data is rendered straight into the page. so
// this fetches the html and extracts a.group.cursor-pointer.rounded-sm (40 of them when we
// looked). more brittle than an endpoint: restyle the page and this breaks.
//
// do not edit: re-run `npm run synth -- zed` instead.

import { parse } from "node-html-parser";

export interface ZedRow {
  title: string;
  repo_count: string;
  description: string;
  author: string;
}

export class ZedClient {
  async call(): Promise<ZedRow[]> {
    const res = await fetch("https://zed.dev/extensions");
    if (!res.ok) throw new Error(`zed: ${res.status} ${res.statusText}`);

    const root = parse(await res.text());
    return root.querySelectorAll("a.group.cursor-pointer.rounded-sm").map((node) => ({
      "title": pick(node, "p@0"),
      "repo_count": pick(node, "p@1"),
      "description": pick(node, "p@2"),
      "author": pick(node, "p@3"),
    }));
  }
}

function pick(node: any, selector: string): string {
  // "p@2" means the third <p> anywhere inside the row — css can't say that
  // when the tags sit under different parents, which here they do
  const at = /^(.+)@(\d+)$/.exec(selector);
  const target = selector === "."
    ? node
    : at
      ? node.querySelectorAll(at[1]!.trim())[Number(at[2])]
      : node.querySelector(selector);
  return target?.text.trim().replace(/\s+/g, " ") ?? "";
}
